CREATE OR REPLACE FUNCTION public.guard_credit_approval_task() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND (CASE WHEN TG_OP='INSERT' THEN NEW.credit_profile_id IS NOT NULL ELSE OLD.credit_profile_id IS NOT NULL END) THEN RAISE EXCEPTION 'Kreditlimitfreigaben ausschließlich über die Freigabeentscheidung bearbeiten' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;